package cn.zhuatech.idp.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class DocumentPostingGovernanceServiceTest{private final DocumentPostingGovernanceService service=new DocumentPostingGovernanceService();@Test void postsVerifiedDocument(){var r=service.assess(new DocumentPostingGovernanceService.Request("D1",true,false,true,true,true,true,98,false,false));assertThat(r.decision()).isEqualTo(DocumentPostingGovernanceService.Decision.POST);}@Test void rejectsInvalidDocument(){var r=service.assess(new DocumentPostingGovernanceService.Request("D2",false,true,false,false,false,false,99,false,false));assertThat(r.blockers()).hasSize(6);}@Test void reviewsConfidenceAndHighValue(){var r=service.assess(new DocumentPostingGovernanceService.Request("D3",true,false,true,true,true,true,70,true,false));assertThat(r.actions()).hasSize(2);}}
